BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def S(w):return 'https://www.etymonline.com/word/'+w
def M(w):return 'https://www.merriam-webster.com/dictionary/'+w
def A(h,w,m):return h+[[w,m]]
B=[['拉丁 pingere，过去分词 pictus','绘画、着色；用图像表现']]
PAINT=B+[['古法语 peindre → 分词 peint → peintier','绘画、涂色'],['中古英语 peinten／peynten → paint','画；涂漆；后来也用于言语描绘']]
PICTURE=B+[['拉丁 pictura → 中古英语 picture','绘画、图画'],['英语 picture 名词 → 动词','图像、照片；整体情形；在脑中想象']]
DEPICT=B+[['拉丁 de- + pingere → depingere，分词 depictus','画出、描绘'],['中古英语 depicten → depict','用画面、文字等描绘']]
PIGMENT=B+[['拉丁 pigmentum → 中古英语 pigment','着色材料、颜料'],['英语 pigment','颜料；生物体内的色素']]
SPICE=B+[['拉丁 pigmentum → 晚期拉丁 pigmenta','着色材料；植物汁液、香料等相关意义'],['西班牙语 pimienta／pimiento；葡萄牙语也有相关形式','胡椒、椒类的名称']]
BIO='https://www.cancer.gov/publications/dictionaries/cancer-terms/def/pigment'
W=[
E('picture','英 /ˈpɪktʃə/；美 /ˈpɪktʃər/','图画、图片、照片；情形；想象','眼前有一幅图，脑中也可以有一幅图；把事情放在一起理解，又是在看整个 picture。','拉丁 pictura“绘画、图画”来自 pictus，即 pingere 的分词。名词进入英语后再发展出 picture 动词；现代不要把 pic 当成更早祖先，它反而是 picture 的缩略。',PICTURE,'take a picture 是拍照；draw a picture 是画图。get the picture 是明白情况，see the big picture 是看整体。Picture yourself there 是让你在脑中想象自己身在其中，并不要求真的作画。','take a picture；a picture of...；the big picture；picture yourself doing something。','painting 通常是用颜料画的作品；picture 范围更广，照片、插图和脑中形象都可以。',('Could you take a picture of us by the fountain?','你能在喷泉旁给我们拍张照吗？'),('I can picture the room, but I cannot remember its address.','我能想起房间的样子，却记不起地址。'),('We need the full picture before making a decision.','我们需要了解全貌，再作决定。'),sources=[S('picture'),K('picture')]),
E('paint','/peɪnt/','颜料、油漆；绘画、刷漆；描绘','同样是把颜色放到表面：画家用它表现景物，装修工用它覆盖墙面。','动词经古法语 peintier，接 peindre 的分词 peint，远接拉丁 pingere。英语名词可从动词形成，也有古法语相关名词的借入分析；不是把现代 picture 截短而来。',PAINT+[['英语 paint 名词：动词转用或古法语相关名词影响','用来绘画、涂覆的材料']],'paint a door 是给门刷漆，paint a portrait 是画肖像。paint a bleak picture 则用语言把局面描写得黯淡。名词通常不可数，但不同种类或一盒颜色可用 paints。','wet paint；a coat of paint；paint the wall blue；paint a picture of...。','draw 常突出线条，paint 常使用颜料；pigment 是提供颜色的材料成分，paint 是调制后可涂用的材料。',('They painted the kitchen walls pale green.','他们把厨房墙壁刷成浅绿色。'),('The report paints an optimistic picture of the coming year.','报告把来年的形势描绘得很乐观。'),sources=[S('paint'),K('paint'),M('paint')]),
E('painting','/ˈpeɪntɪŋ/','绘画；刷漆；一幅画作','可以是在说“动手画的这件事”，也可以是在说画完后挂在墙上的那件作品。','paint + -ing，英语动词性名词，中古英语已有记录。表示活动时通常不可数，表示一幅作品时可数。',A(PAINT,'中古英语、英语 paint + -ing → painting','绘画活动；用颜料完成的作品'),'I enjoy painting 说爱好；I bought a painting 说买了一幅画。house painting 是房屋刷漆，不是每次出现 painting 都在说艺术创作。','an oil painting；a painting by...；take up painting；house painting。','picture 可包括照片和插图；painting 通常强调使用颜料的画作。drawing 更常指线条画或素描。',('Painting helps her relax after work.','下班后画画能让她放松。'),('A small painting of the harbour hangs above the desk.','桌子上方挂着一幅小小的港口画。'),sources=[S('painting'),K('painting')]),
E('painted','/ˈpeɪntɪd/','刷过漆的；画出的；描绘了','表面已经上了颜色，或某个形象已经被画出来；它强调 paint 动作完成后的结果。','paint + -ed；/t/ 后的词尾读 /ɪd/。可作动词过去式、过去分词，也可作形容词。',A(PAINT,'英语 paint + -ed → painted','已涂漆、已画出的；已经描绘'),'a painted wooden box 是涂绘过的木盒；a painted landscape 可以是画出的风景。a freshly painted room 指刚刷过漆的房间，不是在评价它是否漂亮。','freshly painted；painted furniture；a painted portrait；painted in bright colours。','painted 描述已经上色或被描绘；colourful 只说色彩丰富，不交代颜色如何形成。',('The painted wooden birds stood along the shelf.','上过彩的木鸟沿架子摆放。'),('She painted the scene from memory.','她凭记忆画出了那个场景。'),sources=[K('painted'),S('paint')]),
E('painter','英 /ˈpeɪntə/；美 /ˈpeɪntər/','画家；油漆工','同样拿着画笔或漆刷，做的是艺术作品还是墙面施工，要从场景判断。','现代可对应 paint + -er，但历史名词经中古英语 peyntour、古法语 peintor，接拉丁 pictor“画者”，有独立借入路线。',B+[['拉丁 pictor → 古法语 peintor → 中古英语 peyntour','从事绘画的人'],['英语 painter','画家；也指粉刷、刷漆的工人']],'portrait painter 是肖像画家；house painter 是房屋油漆工。另有船用系缆的同形词 painter，通常另接表示悬挂的词源，不属于这一绘画义。','a landscape painter；a portrait painter；a house painter；a painter and decorator。','artist 的创作领域更广；painter 在艺术语境中特指绘画者，在装修语境中则是工种。',('The painter is best known for quiet coastal scenes.','这位画家最有名的是宁静的海岸风景画。'),('The painter covered the floor before starting on the walls.','油漆工开始刷墙前先遮住了地板。'),sources=[S('painter'),K('painter')]),
E('paintbrush','/ˈpeɪntbrʌʃ/','画笔；漆刷','前半告诉你做什么，后半告诉你拿什么工具做：把颜料或油漆刷到表面的刷子。','paint + brush，英语复合名词；paint 属本词族，brush 是另一个独立来源的词，不能把全词每一部分都归给 pict-。',A(PAINT,'英语 paint + brush → paintbrush','涂颜料、油漆的笔或刷子'),'可以是细画笔，也可以是较宽的漆刷。具体尺寸、材质由需要决定，词本身不限定为艺术用品。','a fine paintbrush；a wide paintbrush；clean the paintbrush；paintbrush strokes。','brush 单独范围很广，包括牙刷、清洁刷；paintbrush 指用来画或刷漆的那一种。',('Use a fine paintbrush for the small details.','细小的细节要用细画笔。'),('He left the paintbrush beside the open tin.','他把漆刷放在打开的漆罐旁。'),sources=[K('paintbrush'),M('paintbrush')]),
E('paintwork','英 /ˈpeɪntwɜːk/；美 /ˈpeɪntwɜːrk/','漆面；油漆层','手指沿车门划过去，看到的是那层光亮或有划痕的漆面；这个整体表层就是 paintwork。','paint + work，英语复合名词；这里 work 指做出来的表面成果，不是某份油漆工职业。',A(PAINT,'英语 paint + work → paintwork','门、墙、车辆等表面的漆层'),'尤其常见于英式英语，通常不可数。damaged paintwork 说漆面受损；不必表示底下的金属或木材也坏了。','scratched paintwork；damaged paintwork；restore the paintwork；glossy paintwork。','painting 可指刷漆活动；paintwork 通常指留下的漆面。a painting 则往往是一幅画。',('The bicycle has a few scratches in the paintwork.','自行车的漆面上有几道划痕。'),('The old door still has its original paintwork.','旧门还保留着原来的漆面。'),sources=[K('paintwork'),'https://www.oxfordlearnersdictionaries.com/definition/english/paintwork']),
E('repaint','/ˌriːˈpeɪnt/','重新刷漆；重画','原来已经有一层颜色或一幅画，现在再画、再刷一次，可能是修补，也可能换一个样子。','re- 再次 + paint，英语构词；重音落在 paint。这里讲常用动词。',A(PAINT,'英语 re- + paint → repaint','再次涂漆或绘画'),'repaint a room 常是重新粉刷；repaint a scene 可以是重新画这个场景。它不自动说明先前那层已经完全去掉。','repaint the walls；repaint a door；repaint in a darker colour。','touch up 常是局部补漆、修饰；repaint 更容易让人想到重新涂画较完整的部分。',('We plan to repaint the bedroom this summer.','我们计划今年夏天重新粉刷卧室。'),('She decided to repaint the sky in softer colours.','她决定用更柔和的颜色重画天空。'),sources=[K('repaint'),M('repaint')]),
E('unpainted','/ˌʌnˈpeɪntɪd/','未刷漆的；未上色的','看得见木头、金属或底材原来的表面，因为上面还没有那层漆或颜色。','否定 un- + painted；中古英语 unpeinted 等形式已有记录，现代仍是透明的否定结构。',A(PAINT,'中古英语 unpeinted 等 → unpainted','没有涂漆、上色的'),'unpainted wood 指未刷漆的木料，不等于没有经过任何处理。unpainted figures 也可说等待上色的模型或小雕像。','unpainted wood；an unpainted surface；leave something unpainted。','unpainted 说没有漆；repainted 说重新刷过；plain 只是朴素、无装饰，不保证没上漆。',('The room contains a simple table made of unpainted wood.','房间里有张未刷漆的简朴木桌。'),('One side of the model was still unpainted.','模型的一侧还没有上色。'),sources=[K('unpainted'),M('unpainted')]),
E('picturesque','/ˌpɪktʃəˈresk/','风景如画的；富有画意的','不只是能拍成照片，而是景色的形状、颜色和布局让人觉得很适合入画。','英语依 picture 的形式改造、仿造法语 pittoresque；法语又来自意大利语 pittoresco，接 pittore“画家”，远接拉丁 pictor。不能画成法语词从现代英语 picture 派生。',B+[['拉丁 pictor → 意大利语 pittore → pittoresco','画家 → 绘画般的'],['法语 pittoresque → 英语 picturesque','借入时与英语 picture 的形式相联系']],'常形容村庄、港口、风景等有画面美感的地方。日常主要是赞美视觉效果，不是在证明那里生活一定轻松。','a picturesque village；picturesque scenery；a picturesque harbour。','beautiful 范围很广；picturesque 更突出可入画的景致。pictorial 则只说与图画有关，不自带好看。',('A narrow bridge leads to the picturesque village.','一座窄桥通向那个风景如画的村庄。'),('The guidebook shows the town’s most picturesque streets.','指南展示了镇上最有画意的几条街道。'),sources=[S('picturesque'),K('picturesque')]),
E('pictured','英 /ˈpɪktʃəd/；美 /ˈpɪktʃərd/','图中所示的；拍摄、描绘了；想象了','读到图注里的 pictured above，就把目光移到上面的照片；在故事里，它也可能说某人脑中想到了一个画面。','picture 动词 + -ed；既可表示画面上的呈现，也可承接 picture“想象”的意思。',A(PICTURE,'英语 picture + -ed → pictured','已呈现于图中；已经想象'),'The woman pictured left 是左图所示的女子；I pictured a quiet place 是我想象的是一处安静地方。不是每个 pictured 都涉及真的照片。','pictured above；pictured on the cover；as pictured；pictured herself doing something。','photographed 明确是被拍摄；pictured 可以是拍照、画出，也可以只是在脑中想象。',('The building pictured on the cover is now a museum.','封面图中的建筑现在是一座博物馆。'),('He had pictured a much smaller audience.','他原先想象观众会少得多。'),sources=[K('pictured'),S('picture')]),
E('depict','/dɪˈpɪkt/','描绘；刻画；把……表现为','把一个人或场景呈现给别人，让人看见或在脑中形成印象；用画、文字、电影都可以。','拉丁 de- + pingere 形成 depingere，过去分词 depictus 经中古英语 depicten 进入英语。这里 de- 不是否定，整体已是描画、表现的意思。',DEPICT,'depict someone as brave 是把某人刻画成勇敢的人。这个人实际如何，仍要看材料；depict 首先说作品怎样表现他。','depict a scene；depict life in...；depict someone as...；vividly depict。','describe 强调描述，可很概括；depict 常让人想到较具体的形象或呈现方式，但不限于视觉艺术。',('The mural depicts workers building the railway.','壁画描绘了工人修建铁路的场景。'),('The novel depicts the city as lively but lonely.','小说把这座城市写得热闹却孤独。'),sources=[S('depict'),K('depict')]),
E('depicted','/dɪˈpɪktɪd/','被描绘的；刻画了','人物已经以某种形象进入画面或文字，你现在谈的是作品中呈现出来的那一面。','depict + -ed，英语过去式、过去分词；/t/ 后加 /ɪd/，不是只在词尾附一个 /d/。',A(DEPICT,'英语 depict + -ed → depicted','已经描绘、表现的'),'as depicted in the film 是按电影中的呈现；the events depicted 是被描绘的事件。这里的被动关系很常见。','depicted in a painting；depicted as a hero；the scene depicted。','pictured 常可直接指照片里的人物；depicted 更突出作品如何描绘、刻画。',('The coastline depicted in the painting has changed greatly.','画中描绘的海岸线已经变化很大。'),('The film depicted her as a patient and determined leader.','电影把她刻画成一位耐心而坚定的领导者。'),sources=[K('depicted'),S('depict')]),
E('depiction','/dɪˈpɪkʃən/','描绘、刻画；表现出来的形象','同一个人物可以被不同作品写出不同面貌；每一种呈现方式都可以叫 a depiction。','经法语 dépiction，接晚期拉丁 depictio，来自 depingere 的词干。现代可对应 depict + -ion，但名词有自己的借入路线。',B+[['拉丁 depingere → 晚期拉丁 depictio','描画 → 描画行为或呈现'],['法语 dépiction → 英语 depiction','描绘、刻画；一种呈现']],'a realistic depiction of family life 是对家庭生活的写实呈现。可以说画面，也可以说小说、电影如何塑造人和事件。','a vivid depiction；a realistic depiction of...；the depiction of a character。','description 可是一段说明；depiction 更常侧重形成了怎样的形象。representation 范围更广，也有代表等意思。',('Readers praised the book’s honest depiction of grief.','读者称赞这本书对悲伤的描写很真实。'),('The exhibition compares three depictions of the same harbour.','展览比较了对同一港口的三种描绘。'),sources=[S('depiction'),K('depiction')]),
E('pictorial','英 /pɪkˈtɔːriəl/；美 /pɪkˈtɔːriəl/','图画的；用图片呈现的','介绍一本地方历史，不只靠长篇文字，而用照片、地图和插图把它讲出来，这就是 pictorial 的方向。','拉丁 pictor 画家 → pictorius“绘画的”，英语再配 -al。不是把 picture 原样加 -ial；形式里的 pictor- 有自己的拉丁来源。',B+[['拉丁 pictor → pictorius','画家 → 绘画的'],['英语依 pictorius 配 -al → pictorial','关于图画的；以图片表现的']],'a pictorial guide 是图片式指南；pictorial evidence 是图像证据。这个词说媒介或呈现方式，不自动表示景色优美。','a pictorial guide；a pictorial history；pictorial representation；pictorial evidence。','picturesque 是风景如画、好看；pictorial 是与图片有关、通过图片呈现。',('The museum published a pictorial history of the neighbourhood.','博物馆出版了一部街区图史。'),('Pictorial instructions show how the parts fit together.','图示说明展示了各部件如何装配。'),sources=[S('pictorial'),K('pictorial')]),
E('pictogram','/ˈpɪktəɡræm/','图示符号；象形图；图形统计图','一个小人、一辆自行车或一只行李箱，能把某种信息压缩成一个容易认出的图形。','现代 picto- 接拉丁 pictus“画出的”，-gram 接希腊 gramma“写下、画出的东西”；这是利用古典构件新造的词，不是古拉丁语已有的整词。',B+[['拉丁 pictus → 现代 picto-；希腊 gramma → -gram','画的 + 记录、图形'],['英语 pictogram','用图像表示信息的符号；图形统计图']],'公共标识常用 pictogram。统计图里也可以让一个小图标代表若干数量，所以读图时仍需看图例，不能默认一个图标只算一个。','a warning pictogram；a pictogram on a sign；read the key to a pictogram。','icon 常指界面图标或代表性形象；pictogram 更突出用图像传达对象、动作或数量。两词部分用法重叠。',('A suitcase pictogram marks the baggage area.','行李箱图示标出了行李区域。'),('In this pictogram, each tree represents ten planted trees.','在这幅图形统计图中，每个树形图标代表十棵已种的树。'),sources=[S('pictogram'),M('pictogram')]),
E('pictograph','英 /ˈpɪktəɡrɑːf/；美 /ˈpɪktəɡræf/','图画符号；象形图；图形统计图','把可辨认的图形拿来记录、传达意思；看的人需要理解图形在那套表达方式中代表什么。','picto- 接拉丁 pictus，-graph 接希腊写画构件；十九世纪英语组合而成。不是从现代 photograph 删掉几个字母。',B+[['拉丁 pictus → picto-；希腊写画构件 → -graph','画的 + 写画、记录之物'],['英语 pictograph','表达信息的图画符号；图形统计图']],'在历史文字研究中，可指表意的图画符号；在课堂中，也常指用图标展示数量的图。具体含义看语境，不要把一切古代画作都当成完整文字系统。','a rock pictograph；a pictograph showing quantities；interpret a pictograph。','pictograph 和 pictogram 常可互换；实际学科可能有更细分类，不能只凭 -graph 与 -gram 就断定本质不同。',('The guide explained the animal pictographs on the rock wall.','讲解员解释了岩壁上的动物图画符号。'),('The students made a pictograph to compare their favourite fruits.','学生做了一幅图形统计图，比较大家最喜欢的水果。'),sources=[S('pictograph'),M('pictograph')]),
E('pigment','/ˈpɪɡmənt/','颜料；色素','颜色背后有具体的着色物质：画中的蓝、叶子的绿、皮肤的颜色，都可以从 pigment 这一层去理解。','拉丁 pigmentum 来自 pingere 的相关词干加 -mentum，表示着色材料；经中古英语进入现代英语。拼写里的 pig 不是“猪”。',PIGMENT,'艺术和材料中常指提供颜色的颜料物质；生物学中指使组织呈色的色素。paint 通常还含让颜料附着、分散的其他成分，不等同于一份纯 pigment。','a natural pigment；blue pigment；skin pigment；mix pigment with a medium。','在涂料等技术语境，pigment 通常以不溶颗粒分散，dye 通常以溶解的染料形式作用；日常说“颜色”则不一定区分材料。',('The artist mixed a small amount of blue pigment into the medium.','画家把少量蓝色颜料混进调色媒介中。'),('The lesson explains how pigments give leaves their colours.','这节课讲色素如何让叶子呈现颜色。'),sources=[S('pigment'),K('pigment'),M('pigment'),BIO]),
E('pigmentation','/ˌpɪɡmenˈteɪʃən/','色素形成；色素沉着；色素着色状态','讨论的不是把表面涂上油漆，而是色素在组织里形成、分布后，呈现怎样的颜色。','pigment 名词 + -ation，可能受到法语 pigmentation 的影响。英语名词记录早于 pigment 作动词的常见记录，不宜只画成现代动词加后缀。',A(PIGMENT,'英语 pigment 名词 + -ation → pigmentation〔可能有法语范词〕','色素形成及由色素产生的着色状态'),'常见 skin pigmentation，也可用于动物、植物。changes in pigmentation 是色素着色发生变化，词本身不判定这是疾病还是正常差异。','skin pigmentation；changes in pigmentation；differences in pigmentation。','pigment 是物质，pigmentation 是色素形成、分布及着色状态；colour 是更宽泛的可见颜色。',('The study compares pigmentation in the leaves of several varieties.','研究比较了几个品种叶片的色素着色情况。'),('The photographs show natural differences in skin pigmentation.','照片展示了皮肤色素着色的自然差异。'),sources=[S('pigmentation'),K('pigmentation'),BIO]),
E('pigmented','英 /pɪɡˈmentɪd/；美 /ˈpɪɡməntɪd/，也读 /ˈpɪɡˌmentɪd/','含色素的；有颜料着色的','它告诉你材料或组织里有带来颜色的成分，而不只是光线照得看上去变了颜色。','pigment + -ed，可表示具有色素的形容词，也可对应 pigment“用颜料着色”的分词。英美词典收录的重音有差异。',A(PIGMENT,'英语 pigment + -ed → pigmented','含色素、颜料的；经过着色的'),'pigmented cells 是含色素细胞；pigmented coating 是含颜料的涂层。heavily pigmented 常强调颜料或色素含量多，不只表示使用了深颜色。','pigmented cells；a pigmented coating；highly pigmented paint。','painted 指经过涂画；pigmented 说含有或具有色素、颜料，可出现在天然组织中。',('The microscope image shows several pigmented cells.','显微图像显示了几个含色素的细胞。'),('A thin layer of the highly pigmented paint covered the mark.','这种颜料含量高的漆薄薄一层就盖住了痕迹。'),sources=[M('pigmented'),'https://www.collinsdictionary.com/dictionary/english/pigmented',BIO]),
E('pimento','英 /pɪˈmentəʊ/；美 /pɪˈmentoʊ/','多香果；也指甜红椒','读食谱时要先看是哪一种：可能是干燥香料果实，也可能是奶酪酱或橄榄里的甜红椒。','远接拉丁 pigmentum，经晚期拉丁 pigmenta 的植物汁液、香料义。多数所核词源书走西班牙语 pimienta／pimiento；也有葡萄牙语 pimento 借入分析，不能只断言唯一中间路线。',SPICE+[['英语 pimento〔直接借入语有西班牙语、葡萄牙语两种分析〕','多香果；后来也用于甜红椒']],'allspice 义指一种植物的香料果实，并不是把所有香料混在一起。pimento cheese 等搭配里通常指甜红椒，与 pimiento 的拼写重叠。','pimento berries；ground pimento；pimento cheese；pimento peppers。','pimento 可有多香果、甜红椒两义；pimiento 通常指甜椒。两种食材并非同一植物，只是英语名称发生了重叠。',('The recipe lists ground pimento, meaning allspice.','食谱列了磨碎的 pimento，这里指多香果。'),('She spread pimento cheese on the crackers.','她把甜红椒奶酪酱抹在薄脆饼干上。'),sources=[S('pimento'),M('pimento'),K('pimento')]),
E('pimiento','美 /pəˈmentoʊ/，也读 /pəmˈjentoʊ/','甜椒；常指用作填馅、装饰的甜红椒','橄榄中间塞着的一小条红色甜椒，是日常很容易认出这种食材的地方。','来自西班牙语 pimiento，与 pimienta 相联系，远经晚期拉丁 pigmenta 接 pigmentum。它和 pigment 同出更早词源，不表示由现代英语“颜料”变成一种食物。',SPICE+[['西班牙语 pimiento → 英语 pimiento','甜椒；果实、食材及其植株']],'在英语烹饪语境常指肉厚、味道温和的甜椒，可用于橄榄填馅、装饰或奶酪酱。也常写作 pimento，但后者还可能指多香果。','pimiento strips；olives stuffed with pimiento；chopped pimiento；pimiento cheese。','sweet pepper 泛指甜椒；pimiento 通常指其中相关品种或食材称呼，不能反过来把所有辣椒都叫它。',('Each olive was stuffed with a small strip of pimiento.','每颗橄榄里都塞着一小条甜红椒。'),('The cook added chopped pimiento for colour and a mild sweetness.','厨师加入切碎的甜红椒，增添颜色和温和甜味。'),sources=[M('pimiento'),M('pimento'),S('pimento')]),
]
ROOT=dict(id='C1045',meaning='画；着色；用图像表现',core='先想一支笔把颜色落到表面：paint 是画或刷，picture 是形成的图像，depict 是把人和事呈现出来，pigment 是提供颜色的材料。',image='一张图画、一罐颜料和一扇刚刷漆的门，分别对应图像、着色材料和涂画动作。',intro='拉丁 pingere 的过去分词是 pictus，所以 ping-、pig-、pict- 在这组里出现不同面貌。英语分别通过拉丁语、法语和后来的构词吸收这些词；并不是每个词都由现代 picture 直接变出来。',forms='paint 经法语发生了明显形式变化；pict- 常接拉丁分词 pictus；pigment 接 pigmentum。pictorial 有 pictor“画者”的词干。picto- 与 -gram、-graph 组合时，是用拉丁和希腊来源构件形成现代词。',branches=[['图像与想象','picture, pictured, picturesque, pictorial'],['绘画和表面着色','paint, painted, painting, painter, paintbrush, paintwork, repaint, unpainted'],['呈现人物与情景','depict, depicted, depiction'],['用图形传达信息','pictogram, pictograph'],['提供颜色的物质','pigment, pigmentation, pigmented'],['经香料名称走出的食物词','pimento, pimiento']],contrasts='picture 可是照片、画和脑中形象；painting 通常是用颜料画的作品。picturesque 说景色如画，pictorial 说用图片呈现。paint 是可涂用的材料，pigment 是着色成分。pimento 与 pimiento 的食材义要看语境，不能按 pigment 的现代意思硬猜。',practice='The painter used blue pigment to paint a picture of the harbour. 画家使用蓝色颜料画了一幅港口图。The novel depicts the same harbour in words. 小说用文字描绘同一港口。把“谁、材料、动作、成果、表现方式”分开记。',words=[],exclude={})
