 OUT.mkdir(parents=True,exist_ok=True)
 (OUT/'roots_batch200_vid_37.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2))
 (OUT/'words_batch200_vid_37.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
